public override string Convert(long input, GrammaticalGender gender, bool addAnd = true)
{
    if (input == 0)
    {
        return profile.ZeroWord;
    }

    var parts = new List<string>(8);
    var remaining = GetAbsoluteValue(input);

    if (input < 0)
    {
        parts.Add(profile.MinusWord);
