static int CountUnescapedFullMonth(string pattern)
{
    var count = 0;
    var inQuote = false;
    for (var i = 0; i < pattern.Length; i++)
    {
        if (pattern[i] == '\'')
        {
            inQuote = !inQuote;
            continue;
        }

        if (inQuote)
        {
            continue;
        }

        if (pattern[i] == 'M')
        {
            var start = i;
            while (i < pattern.Length && pattern[i] == 'M')
            {
                i++;
            }

            if (i - start >= 4)
            {
                count++;
            }

            i--; // Loop will increment.
        }
    }

    return count;
}
