public static bool TryReadNext(ref Enumerator enumerator, ref string? pendingToken, [NotNullWhen(true)] out string? token)
{
    if (pendingToken != null)
    {
        token = pendingToken;
        pendingToken = null;
        return true;
    }

    if (enumerator.MoveNext())
    {
        token = enumerator.Current.ToString();
        return true;
    }

    token = null;
    return false;
}
