/// <summary>Divide the Somes. For numeric values the behaviour is to divide the Somes (lhs / rhs) For Lst values the behaviour is to divide all combinations of values in both lists to produce a new list Otherwise if the T type derives from IDivisible then the behaviour is to call lhs.Divide(rhs);</summary>
public static T? divide<NUM, T>(T? lhs, T? rhs)
    where T : struct
    where NUM : Num<T>
{
    if (!lhs.HasValue) return lhs; // zero / rhs  = zero
    if (!rhs.HasValue) return rhs; // lhs  / zero = undefined: zero
    return NUM.Divide(lhs.Value, rhs.Value);
}
