public S FoldUntil<S>(
    S state,
    Func<A, Func<S, S>> f,
    Func<(S State, A Value), bool> predicate)
{
    for(var xs = Clone(); !xs.IsEmpty; xs = xs.Tail)
    {
        state = f(xs.Head)(state);
        if (predicate((state, xs.Head))) return state;
    }
    return state;
}
```

