static A[] RemoveAt<A>(A[] array, int index)
{
    if (array.Length == 0)
    {
        return array;
    }

    var narray = new A[array.Length - 1];
    if (index > 0)
    {
        System.Array.Copy(array, 0, narray, 0, index);
    }
    if (index + 1 < array.Length)
    {
        System.Array.Copy(array, index + 1, narray, index, array.Length - index - 1);
    }
    return narray;
}
```

