public S FoldBackWhile<S>(
    S state,
    Func<S, Func<A, S>> f, 
    Func<(S State, A Value), bool> predicate) 
{
    foreach(var x in Clone().AsEnumerable().Reverse())
    {
        if (!predicate((state, x))) return state;
        state = f(state)(x);
    }
    return state;
}
