public async ValueTask<S> FoldWhile<S>(
    S state,
    Func<A, Func<S, S>> f,
    Func<(S State, A Value), bool> predicate)
{
    for(var xs = Clone(); !await xs.IsEmpty; xs = await xs.Tail)
    {
        if (!predicate((state, await xs.Head))) return state;
        state = f(await xs.Head)(state);
    }
    return state;
}
```

