{
    return new Seq<A>(new SeqLazy<A>(Yield(this, f)));
    static IEnumerable<A> Yield(Seq<A> items, Func<A, bool> f)
    {
        foreach (var item in items)
        {
            if (f(item))
            {
                yield return item;
            }
        }
    }
}
