/// <summary>Atomically updates the value by passing the old value to `f` and updating the atom with the result. Note: `f` may be called multiple times, so it should be free of side effects.</summary>
public A Swap(Func<M, A, A> f)
{
    f = f ?? throw new ArgumentNullException(nameof(f));

    SpinWait sw = default;
    while (true)
    {
        var current   = value;
        var currentV  = Box<A>.GetValue(current);
        var newValueA = f(metadata, currentV);
        var newValue  = Box<A>.New(newValueA);
        if (!validator(newValueA))
        {
            return currentV;
        }
        if(Interlocked.CompareExchange(ref value, newValue, current) == current)
        {
            Change?.Invoke(newValueA);
            return newValueA;
        }
        sw.SpinOnce();
    }
}
