/// <summary>Right-associative fold of a structure, lazy in the accumulator. In the case of lists, 'Fold', when applied to a binary operator, a starting value (typically the right-identity of the operator), and a list, reduces the list using the binary operator, from right to left.</summary>
public static virtual K<M, S> FoldM<A, M, S>(
    Func<A, Func<S, K<M, S>>> f, 
    S initialState, 
    K<T, A> ta) 
    where M : Monad<M>
{
    var step = T.FoldStep(ta, initialState);
    return Monad.recur(step, go); 

    K<M, Next<Fold<A, S>, S>> go(Fold<A, S> step)
    {
        switch (step)
        {
            case Fold<A, S>.Done(var state):
                return M.Pure(Next.Done<Fold<A, S>, S>(state));

            case Fold<A, S>.Loop(var state, var value, var next):
                return f(value)(state).Map(s => Next.Loop<Fold<A, S>, S>(next(s)));

            default: 
                throw new NotSupportedException();
        }
    }
}
