static int BitCount(int bits)
{
    var c2 = bits - ((bits >> 1) & 0x55555555);
    var c4 = (c2                 & 0x33333333) + ((c2 >> 2) & 0x33333333);
    var c8 = (c4 + (c4                                >> 4)) & 0x0f0f0f0f;
    return (c8 * 0x01010101) >> 24;
}
