public static virtual int Count<A>(K<T, A> ta)
{
    var step  = T.FoldStep(ta, unit);
    var count = 0;
    while (true)
    {
        switch (step)
        {
            case Fold<A, Unit>.Done(_):
                return count;

            case Fold<A, Unit>.Loop(_, _, var next):
                count++;
                step = next(default);
                break;

            default:
                throw new NotSupportedException();
        }
    }
}
