    while (true)
    {
        var oitems   = Items;
        var onChange = Change;
        var (nitems, changes) = onChange == null
                                    ? (oitems.Map(f), null)
                                    : oitems.MapWithLog(f);
        if (ReferenceEquals(Interlocked.CompareExchange(ref Items, nitems, oitems), oitems))
        {
            AnnounceChanges(oitems, nitems, changes);
            return default;
        }
        else
        {
            sw.SpinOnce();
        }
    }
}
