/// <summary>Atomically swap the underlying Seq. Allows for multiple operations on the Seq in an entirely transactional and atomic way.</summary>
internal Unit SwapInternal(Func<ISeqInternal<A>, ISeqInternal<A>> swap)
{
    SpinWait sw = default;
    while (true)
    {
        var oitems = items;
        var nitems = swap(oitems);
        if(ReferenceEquals(oitems, nitems))
        {
            // no change
            return default;
        }
        if (ReferenceEquals(Interlocked.CompareExchange(ref items, nitems, oitems), oitems))
        {
            return default;
        }
        else
        {
            sw.SpinOnce();
        }
    }
}
