public Unit TakeWhile(Func<A, int, bool> pred)
{
    SpinWait sw = default;
    while (true)
    {
        var oitems = items;
        var nitems = new SeqLazy<A>(oitems.TakeWhile(pred));
        if(ReferenceEquals(oitems, nitems))
        {
            // no change
            return default;
        }
        if (ReferenceEquals(Interlocked.CompareExchange(ref items, nitems, oitems), oitems))
        {
            return default;
        }
        else
        {
            sw.SpinOnce();
        }
    }
}
```

