/// <summary>Map each element of the structure into a monoid, and combine the results with `Append`. This fold is right-associative and lazy in the accumulator. For strict left-associative folds consider `FoldMapBack` instead.</summary>
public static virtual B FoldMapUntil<A, B>(Func<A, B> f, Func<(B State, A Value), bool> predicate, K<T, A> ta)
    where B : Monoid<B>
{
    var step = T.FoldStep(ta, B.Empty);
    while(true)
    {
        switch (step)
        {
            case Fold<A, B>.Done(var state):
                return state;

            case Fold<A, B>.Loop(var state, var value, var next):
                if (predicate((state, value)))
                {
                    return state;
                }
                else
                {
                    step = next(state + f(value));
                }
                break;

            default: 
                throw new NotSupportedException();
        }
    }
}
